import * as THREE from './vendor/three.module.js';

// Dead World: a compact, systemic survival sandbox built for touch and keyboard.
const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.1;
const scene=new THREE.Scene(); scene.background=new THREE.Color('#a5aa91'); scene.fog=new THREE.FogExp2('#9ca28d',.0085);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,420);
scene.add(new THREE.HemisphereLight('#d9e3ca','#34372a',2.05));
const sun=new THREE.DirectionalLight('#ffe3b0',3); sun.position.set(-45,70,30);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const mat=(color,roughness=1)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={grass:mat('#53654a'),road:mat('#454940'),line:mat('#acae91'),concrete:mat('#77786a'),brick:mat('#806651'),plaster:mat('#aaa18a'),dark:mat('#272d29'),roof:mat('#524f44'),glass:mat('#546863'),wood:mat('#594a38'),leaf:mat('#42543e'),trunk:mat('#514536'),skin:mat('#b28e70'),shirt:mat('#566254'),pants:mat('#363d37'),zskin:mat('#89907a'),red:mat('#794b43')};
const boxGeo=new THREE.BoxGeometry(1,1,1), sphereGeo=new THREE.SphereGeometry(1,8,6), cylGeo=new THREE.CylinderGeometry(.22,.28,.8,7);
function cube(parent,x,y,z,sx,sy,sz,material,shadow=true){const o=new THREE.Mesh(boxGeo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=shadow;o.receiveShadow=true;parent.add(o);return o;}
function groupAt(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);return g;}
const ground=new THREE.Mesh(new THREE.PlaneGeometry(420,420),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
// Broken asphalt routes form a navigable small county around a central settlement.
for(let x=-100;x<=100;x+=34)cube(scene,x,.0,0,9,.08,230,mats.road,false);
for(let z=-102;z<=102;z+=34)cube(scene,0,.005,z,230,.08,8,mats.road,false);
for(let x=-100;x<=100;x+=34)for(let z=-102;z<=102;z+=34){
  // scattered painted lane dashes
  for(let k=-2;k<=2;k++)cube(scene,x,.052,z+k*7,.16,.018,2.4,mats.line,false);
}
const buildings=[],trees=[],lootNodes=[],zombies=[],vehicles=[];
const buildingKinds=[['HOUSE','RESIDENTIAL','#998d74'],['MART','GROCERY','#8c7557'],['CLINIC','MEDICAL','#b1a995'],['STATION','POLICE','#5e6970'],['HARDWARE','SUPPLY','#887454'],['MOTEL','MOTEL','#a08f73'],['WAREHOUSE','INDUSTRIAL','#727568']];
let seed=34821;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}function choose(a){return a[Math.floor(rand()*a.length)];}
const buildingSpots=[];
for(let gx=-3;gx<=3;gx++)for(let gz=-3;gz<=3;gz++){
 if(Math.abs(gx)+Math.abs(gz)<2)continue;
 const side=choose([-1,1]),x=gx*34+side*(8+rand()*2),z=gz*34+(rand()-.5)*8;
 buildingSpots.push([x,z]);
 const kindIndex=(Math.abs(gx)+Math.abs(gz)>4)?(rand()<.4?6:0):Math.floor(rand()*buildingKinds.length);const [kind,label,color]=buildingKinds[kindIndex];
 const w=kind==='WAREHOUSE'?17:8+rand()*3,d=kind==='WAREHOUSE'?12:8+rand()*3,h=kind==='WAREHOUSE'?5:4.2+rand()*1.3;
 const g=groupAt(x,z),wall=mat(color),roof=mat(kind==='WAREHOUSE'?'#56594f':choose(['#544940','#62594d','#514c43']));
 cube(g,0,h/2,0,w,h,d,wall);cube(g,0,h+.12,0,w+.45,.35,d+.45,roof);
 // readable dark entrance and front windows
 const door=cube(g,0,1.05,d/2+.012,1.25,2.1,.08,mats.wood);door.userData.door=true;
 for(const wx of [-w*.31,w*.31]){cube(g,wx,2.55,d/2+.018,1.5,1.15,.09,mats.glass);cube(g,wx,2.55,d/2+.075,.09,1.24,.035,mats.wood);}
 const sign=cube(g,0,h-.68,d/2+.08,Math.min(w*.62,8),.55,.11,mat(kind==='CLINIC'?'#e1ded0':'#303a32'));
 // modest storefront sign strip with location type data
 const b={x,z,w,d,h,kind,label,mesh:g,door,looted:false,closed:false,loot:makeLoot(kind)};buildings.push(b);
 // Containers and narrative debris just inside the entry are visible through glass.
 const crate=cube(g,-w*.22,.38,-d*.20,1.15,.76,.9,mat('#62533f'));crate.userData.box=true;
 if(rand()<.75){const trash=groupAt(x+(rand()-.5)*3,z+d*.8);cube(trash,0,.17,0,.8,.34,.65,mat('#4b4d43'));}
}
function makeLoot(kind){const pools={HOUSE:['Canned beans','Bottled water','Bandage','Cereal','Kitchen knife','Batteries'],GROCERY:['Canned beans','Water bottle','Cereal','Tinned peaches','Bottled water','Snack bar'],MEDICAL:['Bandage','Antibiotics','Painkillers','Sterile dressing','Bottled water'],POLICE:['Crowbar','Batteries','Bandage','Ammo box','Water bottle'],SUPPLY:['Hatchet','Hammer','Nails','Duct tape','Crowbar'],MOTEL:['Snack bar','Water bottle','Bandage','Canned beans'],INDUSTRIAL:['Metal pipe','Duct tape','Nails','Work gloves','Batteries']};let pool=pools[kind]||pools.HOUSE;return Array.from({length:3+Math.floor(rand()*4)},()=>choose(pool));}
// Roadsides, yards, and forest edges use lightweight repeated low-poly trees.
function tree(x,z,scale=1){const g=groupAt(x,z);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.22*scale,.38*scale,2.1*scale,6),mats.trunk);trunk.position.y=1.05*scale;trunk.castShadow=true;g.add(trunk);const crown=new THREE.Mesh(new THREE.ConeGeometry(1.45*scale,3.8*scale,7),mat(choose(['#354837','#465940','#526348'])));crown.position.y=3.35*scale;crown.castShadow=true;g.add(crown);trees.push(g);}
for(let i=0;i<165;i++){let x=(rand()-.5)*210,z=(rand()-.5)*210;if(Math.abs(x%34)<8||Math.abs(z%34)<7)continue;tree(x,z,.65+rand()*.65);}
// Player model: readable survivor silhouette with simple animated limbs.
const player=groupAt(0,0);const body=cube(player,0,1.15,0,.66,.9,.42,mats.shirt);const head=new THREE.Mesh(sphereGeo,mats.skin);head.scale.set(.25,.29,.25);head.position.set(0,1.85,0);head.castShadow=true;player.add(head);const backpack=cube(player,0,1.28,-.29,.43,.58,.2,mat('#625b43'));const legs=[];for(const x of [-.19,.19]){const leg=cube(player,x,.48,0,.22,.64,.24,mats.pants);legs.push(leg);}const arms=[];for(const x of [-.43,.43])arms.push(cube(player,x,1.2,0,.19,.68,.2,mats.shirt));
const weaponMesh=cube(player,.68,1.07,.15,.12,.12,1.1,mat('#72634d'));weaponMesh.rotation.x=.15;
// Camera-facing horizon and sun time are updated as world time advances.
const playerState={health:100,stamina:100,hunger:12,thirst:18,temp:18,stress:0,carry:0,fitness:62,strength:48,fitness:64,inventory:[{name:'Metal pipe',qty:1,weight:1.8,condition:83,slot:0},{name:'Snack bar',qty:2,weight:.2,slot:1},{name:'Water bottle',qty:1,weight:.5,slot:2},{name:'Bandage',qty:1,weight:.1,slot:3}],sneak:false,vehicle:null};
const playerRadius=.65;let worldMinutes=7*60+20,day=1,weather='CLEAR',weatherClock=0,elapsed=0,gameEnded=false,activeSlot=0,runHeld=false,attackCooldown=0,saveClock=0;
function makeZombie(x,z,i){const g=groupAt(x,z);const skin=mat(choose(['#848d79','#8c776d','#788576','#9c9580']));const torso=cube(g,0,1.1,0,.62,.9,.4,mat(choose(['#536158','#655448','#4c5653','#6d544c'])));const h=new THREE.Mesh(sphereGeo,skin);h.scale.set(.25,.29,.25);h.position.y=1.82;h.castShadow=true;g.add(h);for(const xx of [-.18,.18])cube(g,xx,.48,0,.21,.65,.23,mat('#343c37'));for(const xx of [-.4,.4])cube(g,xx,1.2,0,.18,.65,.18,skin);const type=rand()<.18?'RUNNER':'SHAMBLER';zombies.push({mesh:g,x,z,hp:type==='RUNNER'?55:65,speed:type==='RUNNER'?2.15:1.05,state:'wander',target:null,alert:0,attack:0,type,active:true,seed:rand()*8});}
for(let i=0;i<23;i++){const a=rand()*Math.PI*2,r=14+rand()*84;makeZombie(Math.cos(a)*r,Math.sin(a)*r,i);}
// A drivable abandoned pickup and a fuel point make exploration more than walking.
function makeVehicle(x,z){const g=groupAt(x,z);cube(g,0,.62,0,3.6,.8,1.65,mat('#665c46'));cube(g,-.15,1.2,0,1.9,.55,1.45,mat('#56645d'));for(const xx of [-1.15,1.15])for(const zz of [-.86,.86]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.35,.35,.2,10),mat('#222522'));w.rotation.z=Math.PI/2;w.position.set(xx,.37,zz);g.add(w);}vehicles.push({mesh:g,x,z,fuel:63,health:72,occupied:false});}
makeVehicle(-10,6);makeVehicle(75,-35);
function roundRect(){ }
// Persistence survives refresh, including player condition, position, containers and the simulation clock.
function saveGame(){try{const data={x:player.position.x,z:player.position.z,rotation:player.rotation.y,state:playerState,worldMinutes,day,weather,looted:buildings.map(b=>b.looted),zombies:zombies.map(z=>({x:z.x,z:z.z,hp:z.hp,state:z.state})),vehicles:vehicles.map(v=>({x:v.x,z:v.z,fuel:v.fuel,health:v.health}))};localStorage.setItem('deadworld-save',JSON.stringify(data));}catch(e){}}
function loadGame(){try{const d=JSON.parse(localStorage.getItem('deadworld-save'));if(!d)return;player.position.set(d.x||0,0,d.z||0);player.rotation.y=d.rotation||0;Object.assign(playerState,d.state||{});worldMinutes=d.worldMinutes||worldMinutes;day=d.day||1;weather=d.weather||weather;(d.looted||[]).forEach((v,i)=>{if(buildings[i])buildings[i].looted=v});(d.zombies||[]).forEach((v,i)=>{if(zombies[i])Object.assign(zombies[i],v)});(d.vehicles||[]).forEach((v,i)=>{if(vehicles[i])Object.assign(vehicles[i],v)});return true;}catch(e){return false;}}
const resumed=loadGame();
function showToast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),2100);}
function updateHUD(){const s=playerState;document.querySelector('#health-fill').style.width=s.health+'%';document.querySelector('#stamina-fill').style.width=s.stamina+'%';document.querySelector('#health-value').textContent=Math.round(s.health);document.querySelector('#stamina-value').textContent=Math.round(s.stamina);document.querySelector('#hunger').textContent=Math.round(s.hunger);document.querySelector('#thirst').textContent=Math.round(s.thirst);document.querySelector('#temp').textContent=Math.round(s.temp)+'°';document.querySelector('#clock').textContent=String(Math.floor(worldMinutes/60)%24).padStart(2,'0')+':'+String(Math.floor(worldMinutes%60)).padStart(2,'0');document.querySelector('#day').textContent=String(day).padStart(2,'0');document.querySelector('#weather').textContent=weather;document.querySelector('#condition').textContent=s.health<35?'CRITICAL':s.thirst>70?'DEHYDRATED':s.hunger>75?'STARVING':'STEADY';}
function nearestThing(){let best=null,dist=4.2;for(const b of buildings){const d=Math.hypot(player.position.x-b.x,player.position.z-b.z);if(d<dist){best={type:'building',obj:b,d};dist=d;}}for(const v of vehicles){const d=Math.hypot(player.position.x-v.x,player.position.z-v.z);if(d<dist){best={type:'vehicle',obj:v,d};dist=d;}}for(const z of zombies){if(z.hp>0){const d=Math.hypot(player.position.x-z.x,player.position.z-z.z);if(d<dist){best={type:'zombie',obj:z,d};dist=d;}}}return best;}

