function nearestThing(){let best=null,dist=4.2;for(const b of buildings){const d=Math.hypot(player.position.x-b.x,player.position.z-b.z);if(d<dist){best={type:'building',obj:b,d};dist=d;}}for(const v of vehicles){const d=Math.hypot(player.position.x-v.x,player.position.z-v.z);if(d<dist){best={type:'vehicle',obj:v,d};dist=d;}}for(const z of zombies){if(z.hp>0){const d=Math.hypot(player.position.x-z.x,player.position.z-z.z);if(d<dist){best={type:'zombie',obj:z,d};dist=d;}}}return best;}
const overlay=document.querySelector('#overlay'),panel=document.querySelector('#panel');
function openPanel(html){panel.innerHTML=html;overlay.classList.remove('hidden');}
function closePanel(){overlay.classList.add('hidden');}
function startNew(){if(!resumed){player.position.set(0,0,0);}closePanel();showToast(resumed?'Your last night is still waiting.':'Ashfall County — find supplies. Keep quiet.');saveGame();}
function intro(){openPanel(`<div class="eyebrow">ASHFALL COUNTY · SURVIVAL SANDBOX</div><h1>THE WORLD <em>WENT QUIET.</em></h1><p>Day ${String(day).padStart(2,'0')} after the fall. The roads are empty, the houses are not. Search what remains, keep your head down, and make it through the night.</p><div class="row"><span>FIELD CONDITION</span><small>${weather} · ${String(Math.floor(worldMinutes/60)%24).padStart(2,'0')}:${String(Math.floor(worldMinutes%60)).padStart(2,'0')}</small></div><div class="row"><span>NEARBY SIGNALS</span><small>${zombies.filter(z=>Math.hypot(z.x-player.position.x,z.z-player.position.z)<28).length} MOVEMENT</small></div><div class="button-row"><button class="primary" id="start-run">${resumed?'CONTINUE SURVIVING':'ENTER ASHFALL'}</button><button id="open-map">FIELD MAP</button></div><p style="font:9px 'DM Mono';color:#929a88;margin-bottom:0">Auto-save enabled · WASD / touch joystick · E or USE to interact</p>`);document.querySelector('#start-run').onclick=startNew;document.querySelector('#open-map').onclick=()=>{closePanel();showMap();};}
function showInventory(){const entries=playerState.inventory;const cards=entries.length?entries.map((it,i)=>`<div class="item-card"><b>${it.name} ${it.qty>1?'×'+it.qty:''}</b><small>${it.weight} kg · ${it.condition||100}% condition</small><button data-use="${i}" style="margin-top:8px;padding:5px 8px;font-size:8px">${it.name.includes('Water')||it.name.includes('Snack')||it.name.includes('beans')||it.name.includes('Cereal')||it.name.includes('peaches')?'USE':'DROP'}</button></div>`).join(''):'<p>Nothing left but the weight of it.</p>';
 openPanel(`<div class="eyebrow">SURVIVOR KIT · ${playerState.inventory.reduce((a,x)=>a+x.weight*x.qty,0).toFixed(1)} / 18 KG</div><h1>PACK <em>CONTENTS</em></h1><div class="inventory-grid">${cards}</div><div class="row"><span>HEALTH / ENDURANCE</span><small>${Math.round(playerState.health)}% / ${Math.round(playerState.stamina)}%</small></div><div class="row"><span>HUNGER / THIRST</span><small>${Math.round(playerState.hunger)}% / ${Math.round(playerState.thirst)}%</small></div><div class="button-row"><button id="close-inv" class="primary">BACK TO THE STREET</button><button id="save-now">SAVE NOW</button></div>`);
 panel.querySelector('#close-inv').onclick=closePanel;panel.querySelector('#save-now').onclick=()=>{saveGame();showToast('Progress secured locally.');};panel.querySelectorAll('[data-use]').forEach(btn=>btn.onclick=()=>useItem(Number(btn.dataset.use)));}
function useItem(i){const item=playerState.inventory[i];if(!item)return;let used=false;
 if(/Water/i.test(item.name)){playerState.thirst=Math.max(0,playerState.thirst-38);used=true;}
 else if(/Snack|beans|Cereal|peaches/i.test(item.name)){playerState.hunger=Math.max(0,playerState.hunger-30);playerState.stamina=Math.min(100,playerState.stamina+8);used=true;}
 else if(/Bandage|dressing/i.test(item.name)&&playerState.health<100){playerState.health=Math.min(100,playerState.health+26);used=true;}
 else if(/Painkillers|Antibiotics/i.test(item.name)){playerState.stress=Math.max(0,playerState.stress-12);used=true;}
 else if(i!==0){showToast('Dropped '+item.name+'.');playerState.inventory.splice(i,1);showInventory();saveGame();return;}
 if(used){item.qty--;if(item.qty<=0)playerState.inventory.splice(i,1);showToast('Used '+item.name+'.');updateHUD();showInventory();saveGame();}else showToast('That will not help right now.');}
function showLoot(b){if(b.looted){showToast('Nothing useful left in this place.');return;}const items=b.loot.splice(0);b.looted=true;items.forEach(name=>{const found=playerState.inventory.find(x=>x.name===name);if(found)found.qty++;else playerState.inventory.push({name,qty:1,weight:/Water|beans|Cereal|peaches/i.test(name)?.5:.6,condition:Math.floor(70+rand()*30)});});playerState.carry=playerState.inventory.reduce((a,x)=>a+x.weight*x.qty,0);showToast(`${b.kind}: ${items.length} useful finds. Search noise carries.`);for(const z of zombies){const d=Math.hypot(z.x-player.position.x,z.z-player.position.z);if(d<45){z.alert=Math.max(z.alert,16);z.target=player.position.clone();z.state='investigate';}}saveGame();}
function interact(){const near=nearestThing();if(!near){showToast('Nothing close enough to interact with.');return;}
 if(near.type==='building'){const b=near.obj;if(near.d<2.6){b.closed=!b.closed;b.door.rotation.y=b.closed?-.9:0;showToast(b.closed?`${b.kind} door opened.`:`${b.kind} entry secured.`);}else showLoot(b);}
 if(near.type==='vehicle'){const v=near.obj;if(!playerState.vehicle){playerState.vehicle=v;v.occupied=true;showToast(`Pickup started · ${Math.round(v.fuel)}% fuel. Use WASD to drive.`);}else{playerState.vehicle=null;v.occupied=false;showToast('You climb out of the pickup.');}}
 if(near.type==='zombie'){attack();}}
function showMap(){let html='';for(let rz=-6;rz<=6;rz++)for(let rx=-6;rx<=6;rx++){let cls='unknown';if(Math.hypot(rx*13-player.position.x,rz*13-player.position.z)<58)cls='';if(rx===0||rz===0)cls='road';if(buildings.some(b=>Math.round(b.x/17)===rx&&Math.round(b.z/17)===rz))cls+=' building';if(Math.abs(rx*17-player.position.x)<8&&Math.abs(rz*17-player.position.z)<8)cls+=' player';html+=`<i class="map-cell ${cls}"></i>`;}
 openPanel(`<div class="eyebrow">ASHFALL COUNTY · LOCAL SKETCH</div><h1>FIELD <em>MAP</em></h1><div class="map-grid">${html}</div><div class="row"><span>YELLOW DOT</span><small>YOU ARE HERE</small></div><p>Unexplored edges stay blank. Roads can carry sound much farther than a quiet walk through the trees.</p><div class="button-row"><button class="primary" id="close-map">RETURN TO WORLD</button><button id="mark-map">DROP A MARKER</button></div>`);document.querySelector('#close-map').onclick=closePanel;document.querySelector('#mark-map').onclick=()=>showToast('Marker placed in your field notes.');}

